<?php if(!$vmState['mail_originals_available']):?><p><?= e($vmI('Die Zuordnung der Einzelvorgänge wurde für diese frühere Bestätigung nicht gespeichert.')) ?></p><?php else:$vmSearch('mail_originals','Vorgemerkte Einzelvorgänge durchsuchen');$vmError('mail_originals');echo $vmPager('mail_originals');foreach($vmState['mail_originals']['rows']??[]as$mnAccepted):?><article class="personal-voucher-event" data-voucher-mail-accepted-person><h4><?= e($mnAccepted['name']) ?></h4><p><?= e($mnAccepted['email']) ?></p><a class="btn btn-outline theme-secondary dwf-button" href="<?= e(url(['view'=>'portal','tab'=>'vouchers','voucher_scope'=>'manage','voucher_event'=>$vmInput[1],'voucher_task'=>'mail','voucher_mail_section'=>'history','voucher_mail_delivery'=>$mnAccepted['id']])) ?>"><?= e($vmI('Ursprünglichen Versandvorgang öffnen')) ?></a></article><?php endforeach;echo $vmPager('mail_originals');endif ?>
<?php elseif($vmOperation==='mail'&&is_string($vmReceipt['result'])&&preg_match('/^[a-f0-9]{32}$/D',$vmReceipt['result'])):$mnReceiptJob=$vmReceipt['result'];elseif($vmOperation==='cancel-mail'):$mnReceiptJob=$vmInput[2];endif;
if(isset($mnReceiptJob)):?><p><a class="btn btn-outline theme-secondary dwf-button" href="<?= e(url(['view'=>'portal','tab'=>'vouchers','voucher_scope'=>'manage','voucher_event'=>$vmInput[1],'voucher_task'=>'mail','voucher_mail_section'=>'history','voucher_mail_delivery'=>$mnReceiptJob])) ?>"><?= e($vmI('Ursprünglichen Versandvorgang öffnen')) ?></a></p><?php unset($mnReceiptJob);endif ?>
<p><a class="btn btn-outline theme-secondary dwf-button" href="<?= e(url(['view'=>'portal','tab'=>'vouchers','voucher_scope'=>'manage','voucher_event'=>$vmInput[1],'voucher_task'=>'mail','voucher_mail_section'=>'history'])) ?>"><?= e($vmI('Versandverlauf dieser Veranstaltung öffnen')) ?></a></p>
